import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Entities – Write","description":"","frontmatter":{"title":"Entities – Write"},"headers":[],"relativePath":"api/reference/entities-write.md","filePath":"api/reference/entities-write.md"}`),a={name:`api/reference/entities-write.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="entities-–-write" tabindex="-1">Entities – Write <a class="header-anchor" href="#entities-–-write" aria-label="Permalink to “Entities – Write”">​</a></h1><div><p>Operations of the tag <strong>Entities – Write</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="deleteEntity" tabindex="-1">Delete an entity from the repository (US-074, REQ-146, UC-10) <a class="header-anchor" href="#deleteEntity" aria-label="Permalink to “Delete an entity from the repository (US-074, REQ-146, UC-10)”">​</a></h2><p><code>DELETE /entities/{id}</code> · <code>deleteEntity</code></p><p>Soft-deletes an element entity or a connection (ADR-019). The entity, its children on all levels (at most 10) and every active connection with the entity or one of the children as endpoint are deleted in one transaction, with one time and actor; the cascade always applies. Deleted entities leave catalogs and baselines, their history and audit trail stay, and their external IDs stay reserved (#70). The entity itself has no cascade origin; the others record it as the entity whose deletion took them along, the reason <code>cascade: entity &lt;id&gt; deleted</code> and the audit event <code>entity.cascade-deleted</code>; the entity is audited as <code>entity.deleted</code>. Versions do not change. The answer lists every deleted ID, the entity first, then children and connections, so that a client can remove them.</p><p>A connection is deleted alone. A structuring aid (its own operation <code>deleteStructuringAid</code> moves the children to the top level) and an automatic composition connection (changing the parent removes it) give 422 naming <code>entityId</code>.</p><p><code>If-Match</code> with the current version is required: 428 without it, 412 <code>stale-version</code> when the entity changed meanwhile. An open issue of a solution on the entity, a child or a connection gives 409 <code>entity-blocked</code>. Deleting a set that holds a connection of a type used as <code>scopingConnectionType</code> also needs <code>visibility-scope:assign</code> (REQ-161). Deltas <code>modified</code> and <code>retiring</code> of active solutions on the deleted entities become deletion conflicts of those solutions (<code>previewEntityDeletion</code> names them beforehand).</p><p><strong>Access</strong>: permission <code>entity:delete</code>; additionally <code>visibility-scope:assign</code> when the deleted set holds a connection of a type used as scopingConnectionType</p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>yes</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The entity and its cascade are deleted</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or already deleted entity</td><td>–</td></tr><tr><td>409</td><td>The entity, a child or a connection has an open issue of a solution (<code>urn:oea:problem:entity-blocked</code>, extension member <code>entities</code>). Nothing changes.</td><td><code>urn:oea:problem:entity-blocked</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>422</td><td>A structuring aid or an automatic composition connection (problem type <code>urn:oea:problem:validation-failed</code> naming <code>entityId</code>); nothing changes</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="previewEntityDeletion" tabindex="-1">Preview of the deletion of an entity (US-074, REQ-146, SCR-021) <a class="header-anchor" href="#previewEntityDeletion" aria-label="Permalink to “Preview of the deletion of an entity (US-074, REQ-146, SCR-021)”">​</a></h2><p><code>GET /entities/{id}/deletion</code> · <code>previewEntityDeletion</code></p><p>What <code>deleteEntity</code> would do: the name and current version of the entity (the <code>If-Match</code> of the deletion), the number of its children on all levels, the number of active connections deleted with it and its children, and the active solutions (not <code>implemented</code> or <code>archived</code>) with a delta <code>modified</code> or <code>retiring</code> on any entity of the set, each with the number of such deltas. Changes nothing and locks nothing. An unknown or deleted entity gives 404, a structuring aid or an automatic composition connection 422 naming <code>entityId</code>.</p><p><strong>Access</strong>: permission <code>entity:delete</code></p><h3 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr></tbody></table><h3 id="responses-1" tabindex="-1">Responses <a class="header-anchor" href="#responses-1" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The preview</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or deleted entity</td><td>–</td></tr><tr><td>422</td><td>A structuring aid or an automatic composition connection (<code>validation-failed</code> naming <code>entityId</code>)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="restoreDeletedEntity" tabindex="-1">Restore a deleted entity with its cascade (REQ-159, ADR-019) <a class="header-anchor" href="#restoreDeletedEntity" aria-label="Permalink to “Restore a deleted entity with its cascade (REQ-159, ADR-019)”">​</a></h2><p><code>POST /entities/{id}/undelete</code> · <code>restoreDeletedEntity</code></p><p>Undeletes an entity (the path <code>/entities/{id}/restore</code> restores a version). The entity and what its deletion took along are restored in one transaction: its descendants with the same cascade origin and deletion time, and the connections of that cascade with an endpoint among them, whose endpoints are active afterwards. Versions do not change, and each restored entity is audited as <code>entity.undeleted</code>. An entity deleted before the cascade origin existed is restored alone. Rows deleted earlier or by another deletion are never restored, even in the same instant.</p><p>A connection whose other endpoint is still deleted (<code>endpoint-deleted</code>), or an automatic composition connection whose child no longer has that parent (<code>parent-changed</code>), stays deleted and is listed in <code>notRestored</code>. An element entity whose parent is deleted, or whose subtree would end more than 10 levels below the root, is placed at the top level as a new version (audited as <code>entity.parent-changed</code>) and listed in <code>movedToTopLevel</code>. A connection restored directly needs both endpoints active (409 <code>connection-not-restorable</code>, extension member <code>reason</code> <code>endpoint-deleted</code>).</p><p><code>If-Match</code> with the version of the deleted entity is required: 428 without it, 412 <code>stale-version</code> when it differs. Restoring a set that holds a connection of a type used as <code>scopingConnectionType</code> also needs <code>visibility-scope:assign</code> (REQ-161). The version restore (<code>restoreEntity</code>) of a deleted entity answers 409 <code>entity-deleted</code>: undelete first.</p><p><strong>Access</strong>: permission <code>entity:restore</code>; additionally <code>visibility-scope:assign</code> when the restored set holds a connection of a type used as scopingConnectionType</p><h3 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>yes</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="responses-2" tabindex="-1">Responses <a class="header-anchor" href="#responses-2" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The entity and its cascade are restored</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown entity</td><td>–</td></tr><tr><td>409</td><td>The entity is not deleted (<code>urn:oea:problem:entity-not-deleted</code>), or a connection restored directly has a deleted endpoint (<code>urn:oea:problem:connection-not-restorable</code>, extension member <code>reason</code>); nothing changes</td><td><code>urn:oea:problem:entity-not-deleted</code>, <code>urn:oea:problem:connection-not-restorable</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="batchWriteEntities" tabindex="-1">Create/update entities and connections in batch <a class="header-anchor" href="#batchWriteEntities" aria-label="Permalink to “Create/update entities and connections in batch”">​</a></h2><p><code>POST /entities/batch</code> · <code>batchWriteEntities</code></p><p>Writes up to 500 entities and 500 connections in one request. The preferred endpoint for external systems with <code>strategy: upsert</code> (ADR-026). <code>?dryRun=true</code> → validation without persisting. Connections are written after the entities; their endpoints are checked against the connection metatype (codes <code>SOURCE_REQUIRED</code>, <code>SOURCE_AMBIGUOUS</code>, <code>SOURCE_NOT_FOUND</code>, <code>SOURCE_NOT_ALLOWED</code>, the same for <code>TARGET_</code>, <code>METATYPE_NOT_CONNECTION</code> and <code>ENDPOINT_CHANGE_NOT_SUPPORTED</code>). An update of an entity with an open issue of a solution fails with <code>OPEN_ISSUES</code> (US-153 AC1). Not supported yet: <code>dryRun=true</code> (US-141 AC3) is rejected with 422; <code>parentId</code> and <code>lifecycle</code> are item errors. <code>X-Agent-Id</code> is stored only as the informational audit field <code>agent_label</code> (ADR-033 §7). A batch with a connection of a metatype that is the <code>scopingConnectionType</code> of a property definition needs <code>visibility-scope:assign</code>; without it the whole batch is rejected with 403 (REQ-161). A value of a <code>role-restricted</code> property, set or removed, needs one of its write roles, and a value of a <code>connection-scoped</code> property an existing entity in the writer&#39;s scope; otherwise the whole batch is rejected with 403 (REQ-126, REQ-127). A property not named keeps its value.</p><p>An item whose external ID belongs to a deleted entity is rejected with <code>EXTERNAL_ID_DELETED</code>, and an atomic batch changes nothing. Only an <code>upsert</code> item of a writer who also holds <code>entity:restore</code> restores the entity with its cascade and then updates it (<code>restored: true</code>, audited as <code>entity.undeleted</code>, #70); <code>create-only</code> and <code>skip-existing</code> never restore, and the external ID is never reused by a new entity. A restored set that holds a connection of a scoping type needs <code>visibility-scope:assign</code> (403). A connection item is restored only with active endpoints.</p><p><strong>Access</strong>: permission <code>entity:write</code>; additionally <code>visibility-scope:assign</code> when a connection of a type used as scopingConnectionType is written; additionally <code>entity:restore</code> when an upsert item names the external ID of a deleted entity</p><h3 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>dryRun</code></td><td>query</td><td>no</td><td>boolean</td><td>–</td></tr><tr><td><code>X-Agent-Id</code></td><td>header</td><td>no</td><td>string</td><td>Informational label of the calling tool (ADR-026, ADR-033 §7). Stored untrusted as <code>agentLabel</code>; never used for attribution, filtering or authorization. Longer values are truncated to 100 characters; control characters are removed.</td></tr><tr><td><code>X-Agent-Run</code></td><td>header</td><td>no</td><td>string</td><td>Informational correlation ID of a run of the calling tool (stored as <code>agentRun</code>)</td></tr></tbody></table><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: BatchWriteRequest</li></ul><h3 id="responses-3" tabindex="-1">Responses <a class="header-anchor" href="#responses-3" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Batch result (also for partial errors if atomic=false)</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Entire batch invalid, nothing written: more entities or connections than the limit, dryRun=true (not supported yet), or atomic=true with at least one faulty item (<code>errors[].field</code> carries the item index, e.g. <code>entities[3].properties</code> or <code>connections[0].sourceExternalId</code>).</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="createConnection" tabindex="-1">Create connection between two entities <a class="header-anchor" href="#createConnection" aria-label="Permalink to “Create connection between two entities”">​</a></h2><p><code>POST /connections</code> · <code>createConnection</code></p><p>Creates a connection, an entity of a connection metatype with a source and a target (US-036, ADR-010). Source and target are referenced by internal ID or <code>externalId</code>; their metatypes must be allowed by the connection metatype (subtypes included) and cannot change afterwards. Without <code>name</code> the connection is named <code>&lt;source name&gt; → &lt;target name&gt;</code>. Properties are checked as for entities. A connection of a metatype that is the <code>scopingConnectionType</code> of a property definition also needs <code>visibility-scope:assign</code>, otherwise 403 (REQ-161). A value of a <code>role-restricted</code> property needs one of its write roles, otherwise 403 (REQ-126); a value of a <code>connection-scoped</code> property cannot be set on creation, because the connection is not yet in the writer&#39;s scope (403, REQ-127).</p><p><strong>Access</strong>: permission <code>entity:write</code>; additionally <code>visibility-scope:assign</code> when a connection of a type used as scopingConnectionType is written</p><h3 id="request-body-1" tabindex="-1">Request body <a class="header-anchor" href="#request-body-1" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: ConnectionWrite</li></ul><h3 id="responses-4" tabindex="-1">Responses <a class="header-anchor" href="#responses-4" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>Connection created</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Source or target entity not found (<code>errors</code> with <code>SOURCE_NOT_FOUND</code> or <code>TARGET_NOT_FOUND</code>)</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Connection or its properties invalid (error codes as in <code>batchWriteEntities</code>)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="setEntityParent" tabindex="-1">Set or clear the parent of an element entity (US-135, UC-13) <a class="header-anchor" href="#setEntityParent" aria-label="Permalink to “Set or clear the parent of an element entity (US-135, UC-13)”">​</a></h2><p><code>PUT /entities/{id}/parent</code> · <code>setEntityParent</code></p><p>Places an element entity under another element entity, or clears the parent with <code>parentEntityId: null</code> (US-135, US-136; REQ-141, REQ-142, ADR-021). The change is versioned like other entity changes: it writes the next version of the child, whose history, versions and diffs show the system field <code>parentEntityId</code> (&quot;Parent&quot;) by name, and the audit event <code>entity.parent-changed</code>; the parent keeps its version. A restore does not restore the parent. Setting the parent the entity already has changes nothing and writes no version and no event (<code>composition.reason</code> <code>unchanged</code>).</p><p>The parent is another element entity that is not deleted; connections have no parent and are no parent. A parent that is the entity itself, one of its descendants, a connection, deleted or unknown, or a subtree that would end more than 10 levels below the root (the root level is level 1) gives 422 naming <code>parentEntityId</code>; a connection as child gives 422 naming <code>entityId</code>.</p><p>When neither entity is a structuring aid and the connection metatype marked as composition (<code>isComposition</code>) allows the metatype of the parent as source and that of the child as target, a connection of it from the parent to the child is created in the same transaction and marked <code>autoCreated</code>; otherwise only the parent is stored and <code>composition.reason</code> says why. Clearing or changing the parent soft-deletes the connection auto-created for the previous parent (<code>removedConnectionId</code>), if it is not deleted yet; a connection written by other means stays.</p><p><code>If-Match</code> with the current version of the child is required: 428 without it, 412 <code>stale-version</code> when the entity changed meanwhile. An entity with an open issue of a solution gives 409 <code>entity-blocked</code> (US-153). Needs <code>entity:write</code>.</p><p><strong>Access</strong>: permission <code>entity:write</code></p><h3 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>yes</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="request-body-2" tabindex="-1">Request body <a class="header-anchor" href="#request-body-2" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: EntityParentUpdate</li></ul><h3 id="responses-5" tabindex="-1">Responses <a class="header-anchor" href="#responses-5" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The parent is set or cleared</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or deleted entity</td><td>–</td></tr><tr><td>409</td><td>The entity has an open issue of a solution (<code>urn:oea:problem:entity-blocked</code>, US-153 AC1); extension member <code>entities</code> with <code>entityId</code>, <code>entityName</code> and its <code>issues</code>. Nothing changes.</td><td><code>urn:oea:problem:entity-blocked</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Problem type <code>urn:oea:problem:validation-failed</code> with <code>invalidFields</code> <code>parentEntityId</code> or <code>entityId</code>; nothing changes</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="createStructuringAid" tabindex="-1">Create a structuring aid (US-136, UC-13) <a class="header-anchor" href="#createStructuringAid" aria-label="Permalink to “Create a structuring aid (US-136, UC-13)”">​</a></h2><p><code>POST /structuring-aids</code> · <code>createStructuringAid</code></p><p>Creates a structuring aid, a purely navigational grouping (US-136, REQ-141): an entity of the built-in metatype &quot;Structuring aid&quot; with <code>isStructuralGrouper</code> set, at the root level or under <code>parentEntityId</code>. It has no properties, no connections and is not part of a solution. The name is trimmed and has 1–255 characters, the description at most 2000. The parent is checked as for <code>setEntityParent</code> (an element entity that is not deleted, at most 10 levels deep); an invalid one gives 422 naming <code>parentEntityId</code>, an invalid name or description 422 naming <code>name</code> or <code>description</code>; a <code>parentEntityId</code> below 1 gives 422 naming <code>parentEntityId</code> too. Writes version 1 and the audit event <code>entity.created</code>. Needs <code>entity:write</code>.</p><p><strong>Access</strong>: permission <code>entity:write</code></p><h3 id="request-body-3" tabindex="-1">Request body <a class="header-anchor" href="#request-body-3" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: StructuringAidCreate</li></ul><h3 id="responses-6" tabindex="-1">Responses <a class="header-anchor" href="#responses-6" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>The structuring aid is created</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Problem type <code>urn:oea:problem:validation-failed</code> with <code>invalidFields</code> <code>name</code>, <code>description</code> or <code>parentEntityId</code>; nothing is created</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="deleteStructuringAid" tabindex="-1">Delete a structuring aid (US-136, UC-13) <a class="header-anchor" href="#deleteStructuringAid" aria-label="Permalink to “Delete a structuring aid (US-136, UC-13)”">​</a></h2><p><code>DELETE /structuring-aids/{id}</code> · <code>deleteStructuringAid</code></p><p>Soft-deletes a structuring aid (ADR-019). Its children move to the root level, each with a new version (<code>entity.parent-changed</code>), and none of them is deleted; the aid is deleted with the audit event <code>entity.deleted</code> (<code>cause</code> <code>structuring-aid-deleted</code>), all in one transaction. An entity that is no structuring aid gives 422 naming <code>entityId</code>. <code>If-Match</code> with the current version of the aid is required (428, 412). The aid or one of its children with an open issue of a solution gives 409 <code>entity-blocked</code>. Needs <code>entity:write</code> and <code>entity:delete</code>.</p><p><strong>Access</strong>: permission <code>entity:write</code>, <code>entity:delete</code></p><h3 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>yes</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="responses-7" tabindex="-1">Responses <a class="header-anchor" href="#responses-7" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>204</td><td>The structuring aid is deleted and its children are at the root level</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Unknown or already deleted entity</td><td>–</td></tr><tr><td>409</td><td>The aid or a child has an open issue of a solution (<code>urn:oea:problem:entity-blocked</code>); nothing changes</td><td><code>urn:oea:problem:entity-blocked</code></td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>422</td><td>The entity is no structuring aid (<code>invalidFields</code> <code>entityId</code>); nothing changes</td><td>–</td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};